(function(){
  'use strict'

  // Tooltip básico
  
  class Tooltip {
    constructor(el, opts={}) {
      this._el = el;
      this._title = el.getAttribute('data-bs-toggle') === 'tooltip'
        ? (el.getAttribute('title') || el.getAttribute('data-bs-title') || '')
        : '';
      el.removeAttribute('title');
      this._tip = null;
      this._init();
    }
    _init() {
      this._el.addEventListener('mouseenter', () => this._show());
      this._el.addEventListener('mouseleave', () => this._hide());
      this._el.addEventListener('focus',      () => this._show());
      this._el.addEventListener('blur',       () => this._hide());
    }
    _show() {
      if (!this._title) return;
      const tip = document.createElement('div');
      tip.className = 'bs-tooltip';
      tip.textContent = this._title;
      Object.assign(tip.style, {
        position:'fixed', background:'rgba(0,0,0,.8)', color:'#fff',
        padding:'4px 10px', borderRadius:'6px', fontSize:'12px',
        zIndex:'9999', pointerEvents:'none', whiteSpace:'nowrap'
      });
      document.body.appendChild(tip);
      const r = this._el.getBoundingClientRect();
      tip.style.left = (r.left + r.width/2 - tip.offsetWidth/2) + 'px';
      tip.style.top  = (r.top - tip.offsetHeight - 6) + 'px';
      this._tip = tip;
    }
    _hide() {
      if (this._tip) { this._tip.remove(); this._tip = null; }
    }
    static getOrCreateInstance(el, opts) {
      return new Tooltip(el, opts);
    }
  }
  window.bootstrap = { Tooltip };
})();
